    val stories = listOf(
        StorySeries(
            id = "the_clockmakers_open_window",
            title = "The Clockmaker's Open Window",
            tagline = "A young apprentice helps a neighbourhood preserve its memories when an old workshop is due to close.",
            parts = listOf(
                StoryPart(1, "The Workshop Above the Bakery", listOf("Above a bakery on Market Road stood a clock repair shop that had been open for more than forty years. Its owner, Mr Bello, planned to retire at the end of the month.", "Tomi visited after school to return a clock that belonged to his grandmother. He found shelves of carefully labelled gears, pendulums, and handwritten repair notes.", "Mr Bello explained that he would keep the tools he needed, but he did not know what should happen to the workshop's collection of clocks and notebooks.")),
                StoryPart(2, "A Question of Time", listOf("Tomi asked whether the clocks could be donated to a museum. Mr Bello said some were ordinary family objects, not valuable antiques, and their owners might still want them back.", "They made a list of every item, its history, and whether it belonged to the shop or a customer. Nothing would be moved until ownership was clear.", "The list revealed that several clocks had been left by people who had moved away years earlier.")),
                StoryPart(3, "The Window Sign", listOf("Tomi suggested placing a notice in the shop window asking former customers to contact them. Mr Bello approved the wording and added a deadline so the request would not remain open indefinitely.", "The notice invited people to reclaim their property or give written permission for an item to be displayed elsewhere.", "Within two days, the bakery owner said three customers had recognised clocks in the window.")),
                StoryPart(4, "A Box of Notes", listOf("While sorting the repair notebooks, Tomi found pages describing how Mr Bello had taught apprentices to solve common problems patiently.", "He asked before copying any pages. Mr Bello agreed to share a small selection, provided customer names and private details were removed.", "Tomi realised the notebooks contained more than technical instructions. They showed how knowledge had passed from one person to another.")),
                StoryPart(5, "The Former Apprentice", listOf("A woman named Sade arrived with a photograph of herself learning to repair a clock at the workshop many years earlier.", "She explained that Mr Bello had encouraged her to continue studying engineering when she doubted her ability. She now maintained equipment at a hospital.", "She offered to help organise a community demonstration, but only if the workshop could be made safe for visitors.")),
                StoryPart(6, "Making Room Safely", listOf("Mr Bello checked the room with the landlord and identified which areas could be opened to the public. Heavy tools and fragile equipment would remain behind a barrier.", "Sade prepared a short demonstration using a practice clock, while Tomi made a simple sign explaining that visitors should not touch the machinery.", "The bakery owner offered the courtyard for the event so the narrow staircase would not become crowded.")),
                StoryPart(7, "The First Tick", listOf("On Saturday, neighbours gathered in the courtyard. Sade showed how a clock's parts work together and invited questions from children and adults.", "Mr Bello demonstrated a repaired clock that had once belonged to the first shopkeeper. He explained that its owner had given permission for it to be displayed.", "Tomi noticed that people were sharing memories without needing the clocks to be expensive or rare.")),
                StoryPart(8, "The Missing Owner", listOf("One clock remained unclaimed. Its label held only the initials A.O. and the year it had been repaired.", "Tomi asked the local library to share the notice through its community board. A librarian recognised the initials as belonging to a retired music teacher.", "The teacher contacted the shop and confirmed that the clock had been left for repair by her late brother. She chose to donate it, with a note about its history.")),
                StoryPart(9, "A New Home for Time", listOf("The community hall agreed to host a small display of donated clocks, each accompanied by a card approved by its owner or family.", "Mr Bello checked the display plan and chose which repair notes could be shared. Sade volunteered to lead occasional demonstrations for students.", "The workshop itself was returned to the landlord in good order, with all customer property accounted for.")),
                StoryPart(10, "The Open Window", listOf("On his final day, Mr Bello opened the workshop window and listened to the familiar sounds of the street below. The room was nearly empty, but the knowledge he had shared was already travelling elsewhere.", "Tomi received a beginner's repair guide that Mr Bello had written especially for the youth club. Sade arranged to visit once a month to teach safe, supervised lessons.", "The clocks continued ticking in their new homes. The workshop closed, but its open window had helped a neighbourhood understand that time is measured not only by clocks, but also by what people teach one another."))
            )
        )
    )
